// Website logic. All numbers come from data/results.js (generated by PS4_Export.R).
(function () {
  "use strict";
  const R = window.RESULTS;
  if (!R) { document.body.insertAdjacentHTML("afterbegin", "<p style='color:red'>data/results.js missing: run PS4_Export.R</p>"); return; }
  const F = R.facts;
  const COL = { accent: "#1f6f5c", neg: "#b4472f", pos: "#2d6db5", grey: "#9aa3b2", ink: "#1d2330" };
  const YLAB = { roa: "ROA (%)", roe: "ROE (%)" };
  const DIG = { roa: 4, roe: 3 };
  const PLOT_CFG = { displayModeBar: false, responsive: true };

  // ---------- formatting ----------
  const signed = (x, d) => (x > 0 ? "+" : x < 0 ? "−" : "") + Math.abs(x).toFixed(d);
  const stars = p => (p < 0.01 ? "***" : p < 0.05 ? "**" : p < 0.1 ? "*" : "–");
  const pp = (x, d = 2) => signed(x, d) + " pp";

  // ---------- facts in the text ----------
  const factText = {
    n_banks: F.n_banks, n_obs: F.n_obs, n_years: F.n_years,
    year_from: F.years[0], year_to: F.years[1],
    mean_env: F.mean_env.toFixed(0), sd_env: F.sd_env.toFixed(0),
    mean_roa: F.mean_roa.toFixed(2) + "%", mean_roe: F.mean_roe.toFixed(1) + "%"
  };
  document.querySelectorAll("[data-fact]").forEach(el => { el.textContent = factText[el.dataset.fact]; });
  document.getElementById("meta-created").textContent = R.meta.created;

  // segmented buttons helper
  function seg(attr, onChange) {
    const btns = document.querySelectorAll("[" + attr + "]");
    btns.forEach(b => b.addEventListener("click", () => {
      btns.forEach(x => { x.classList.toggle("active", x === b); x.setAttribute("aria-pressed", x === b); });
      onChange(b.getAttribute(attr));
    }));
  }

  // ---------- chart 1: raw scatter ----------
  const banks = [...new Set(R.panel.map(r => r.bank))].sort();
  const sel = document.getElementById("bank-select");
  banks.forEach(b => sel.insertAdjacentHTML("beforeend", `<option>${b}</option>`));
  let rawY = "roe";

  function drawRaw() {
    const y = rawY, bank = sel.value;
    const fit = F.fit_raw[y];
    const xs = R.panel.map(r => r.env);
    const x0 = Math.min(...xs), x1 = Math.max(...xs);
    const traces = [{
      x: xs, y: R.panel.map(r => r[y]), mode: "markers", type: "scatter", name: "Bank-year",
      text: R.panel.map(r => `${r.bank}, ${r.year}`),
      hovertemplate: "%{text}<br>Score %{x}<br>" + y.toUpperCase() + " %{y:.2f}%<extra></extra>",
      marker: { size: 9, color: bank ? COL.grey : COL.accent, opacity: bank ? 0.45 : 0.75 }
    }, {
      x: [x0, x1], y: [fit["(Intercept)"] + fit.env * x0, fit["(Intercept)"] + fit.env * x1],
      mode: "lines", type: "scatter", name: "Trend (no controls)", hoverinfo: "skip",
      line: { color: COL.ink, width: 2, dash: "dash" }
    }];
    if (bank) {
      const s = R.panel.filter(r => r.bank === bank);
      traces.push({
        x: s.map(r => r.env), y: s.map(r => r[y]), mode: "lines+markers+text", type: "scatter", name: bank,
        text: s.map(r => String(r.year)), textposition: "top center", hoverinfo: "skip",
        line: { color: COL.pos, width: 2 }, marker: { size: 10, color: COL.pos }
      });
    }
    Plotly.react("chart-raw", traces, {
      margin: { t: 20, r: 20, b: 50, l: 60 }, showlegend: true, legend: { orientation: "h", y: -0.18 },
      xaxis: { title: "Environmental reporting score (points)", zeroline: false },
      yaxis: { title: YLAB[y], zeroline: true, zerolinecolor: "#ccc" },
      plot_bgcolor: "#fff", paper_bgcolor: "#fff"
    }, PLOT_CFG);
    const b = F.slope_raw[y];
    document.getElementById("raw-takeaway").textContent =
      `Without any adjustment, ${F.sd_env.toFixed(0)} more points of reporting go with ${pp(b * F.sd_env)} ${y.toUpperCase()}. ` +
      `Taken at face value, greener reports look good for profits.`;
  }
  sel.addEventListener("change", drawRaw);
  seg("data-y", v => { rawY = v; drawRaw(); });
  drawRaw();

  // ---------- chart 2: controls lab ----------
  const ctrlKeys = Object.keys(R.labels.ctrl);
  const boxes = document.getElementById("ctrl-boxes");
  ctrlKeys.forEach(k => boxes.insertAdjacentHTML("beforeend",
    `<label class="check"><input type="checkbox" value="${k}"> ${R.labels.ctrl[k]}</label>`));
  const cbs = [...boxes.querySelectorAll("input")];
  const idfc = document.getElementById("drop-idfc");
  let labY = "roe";

  function drawLab() {
    const chosen = cbs.filter(c => c.checked).map(c => c.value).sort().join("+");
    const sample = idfc.checked ? "no_idfc" : "all";
    const rows = R.grid.filter(r => r.sample === sample && r.y === labY).slice().sort((a, b) => a.b - b.b);
    const cur = rows.find(r => r.controls === chosen);
    const eff = cur.b * F.sd_env;
    const nNeg = rows.filter(r => r.b < 0).length;

    const big = document.getElementById("lab-number");
    big.textContent = pp(eff) + " " + labY.toUpperCase();
    big.className = "big-number " + (eff < 0 ? "neg" : "pos");
    const names = chosen ? chosen.split("+").map(k => R.labels.ctrl[k].charAt(0).toLowerCase() + R.labels.ctrl[k].slice(1)).join(", ") : "nothing";
    document.getElementById("lab-text").innerHTML =
      `Holding <strong>${names}</strong> constant, banks with ${F.sd_env.toFixed(0)} more points of reporting had an ${labY.toUpperCase()} ` +
      `that was ${Math.abs(eff).toFixed(2)} percentage points ${eff < 0 ? "lower" : "higher"} ` +
      `(95% interval ${pp(cur.lo * F.sd_env)} to ${pp(cur.hi * F.sd_env)}; ${cur.p < 0.05 ? "statistically significant" : "not statistically significant"} at 5%, p = ${cur.p.toFixed(3)}). ` +
      `The sign is negative in ${nNeg} of ${rows.length} combinations.`;

    const idx = rows.map((_, i) => i + 1);
    const isCur = rows.map(r => r.controls === chosen);
    Plotly.react("chart-lab", [{
      x: idx, y: rows.map(r => r.b * F.sd_env), type: "scatter", mode: "markers",
      error_y: { type: "data", symmetric: false, array: rows.map(r => (r.hi - r.b) * F.sd_env),
                 arrayminus: rows.map(r => (r.b - r.lo) * F.sd_env), thickness: 1, width: 0, color: "#c9ced8" },
      text: rows.map(r => r.controls ? r.controls.split("+").map(k => R.labels.ctrl[k]).join(", ") : "no controls"),
      hovertemplate: "%{text}<br>%{y:.2f} pp<extra></extra>",
      marker: { size: isCur.map(c => (c ? 14 : 6)), color: isCur.map((c, i) => (c ? COL.ink : rows[i].b < 0 ? COL.neg : COL.pos)),
                line: { width: isCur.map(c => (c ? 2 : 0)), color: "#fff" } }
    }], {
      margin: { t: 10, r: 10, b: 40, l: 60 }, showlegend: false,
      xaxis: { title: "64 combinations of controls, sorted", showticklabels: false, zeroline: false },
      yaxis: { title: `pp ${labY.toUpperCase()} per ${F.sd_env.toFixed(0)} pts`, zeroline: true, zerolinecolor: COL.ink, zerolinewidth: 1 },
      plot_bgcolor: "#fff", paper_bgcolor: "#fff"
    }, PLOT_CFG);
  }
  cbs.forEach(c => c.addEventListener("change", drawLab));
  idfc.addEventListener("change", drawLab);
  document.getElementById("ctrl-none").addEventListener("click", () => { cbs.forEach(c => (c.checked = false)); drawLab(); });
  document.getElementById("ctrl-all").addEventListener("click", () => { cbs.forEach(c => (c.checked = true)); drawLab(); });
  seg("data-y2", v => { labY = v; drawLab(); });
  drawLab();

  // ---------- table: specifications A-G ----------
  function drawTable(y) {
    const tb = document.querySelector("#ext-table tbody");
    tb.innerHTML = R.ext.filter(r => r.y === y).map(r => {
      const cls = r.b < 0 ? "neg" : "pos";
      return `<tr class="${r.spec === "C" ? "main-row" : ""}">
        <td>${r.spec} · ${r.label}</td>
        <td class="${cls}">${signed(r.b, DIG[y])}</td>
        <td class="${cls}">${pp(r.b * F.sd_env)}</td>
        <td>${stars(r.p)}</td>
        <td>${r.n}</td></tr>`;
    }).join("");
  }
  seg("data-y3", drawTable);
  drawTable("roe");

  // ---------- Q1 answer (numbers from the OVB decomposition) ----------
  const o = F.ovb;
  document.getElementById("answer-1").innerHTML =
    `<p>Short regression: β̂<sub>short</sub> = ${signed(o.b_short, 3)}. Long regression with net NPA: β̂<sub>long</sub> = ${signed(o.b_long, 3)}.</p>
     <p>β̂<sub>short</sub> = β̂<sub>long</sub> + β̂<sub>NPA</sub> · δ̂, with β̂<sub>NPA</sub> = ${signed(o.beta_npa, 2)} (bad loans lower ROE)
     and δ̂ = ${signed(o.npa_on_env, 4)} (banks that report more have fewer bad loans). Bias = (−)·(−) = ${signed(o.bias, 3)} &gt; 0:
     omitting net NPA biases the slope upwards, enough to flip the sign.</p>`;
})();
